1	@import "tailwindcss";
2	
3	:root {
4	  --evo-green: #00FFA7;
5	  --bg-primary: #0C111D;
6	  --bg-card: #182230;
7	  --bg-sidebar: #0a0f1a;
8	  --border: #344054;
9	  --text-primary: #F9FAFB;
10	  --text-secondary: #D0D5DD;
11	  --text-muted: #667085;
12	  /* Workspace File Manager tokens */
13	  --danger: #EF4444;
14	  --warning: #F59E0B;
15	  --surface-hover: #1e2d3d;
16	  --surface-active: #1a2744;
17	  --border-accent: #00FFA7;
18	}
19	
20	* {
21	  box-sizing: border-box;
22	}
23	
24	body {
25	  margin: 0;
26	  font-family: 'Inter', system-ui, -apple-system, sans-serif;
27	  background: var(--bg-primary);
28	  color: var(--text-primary);
29	  -webkit-font-smoothing: antialiased;
30	  -moz-osx-font-smoothing: grayscale;
31	}
32	
33	/* Scrollbar styling */
34	::-webkit-scrollbar {
35	  width: 6px;
36	  height: 6px;
37	}
38	::-webkit-scrollbar-track {
39	  background: var(--bg-primary);
40	}
41	::-webkit-scrollbar-thumb {
42	  background: var(--border);
43	  border-radius: 3px;
44	}
45	::-webkit-scrollbar-thumb:hover {
46	  background: #475467;
47	}
48	
49	/* Markdown content styling */
50	.markdown-content h1 { font-size: 1.75rem; font-weight: 700; margin: 1.5rem 0 1rem; color: var(--text-primary); }
51	.markdown-content h2 { font-size: 1.375rem; font-weight: 600; margin: 1.25rem 0 0.75rem; color: var(--text-primary); }
52	.markdown-content h3 { font-size: 1.125rem; font-weight: 600; margin: 1rem 0 0.5rem; color: var(--text-primary); }
53	.markdown-content p { margin: 0.5rem 0; color: var(--text-secondary); line-height: 1.7; }
54	.markdown-content ul, .markdown-content ol { margin: 0.5rem 0; padding-left: 1.5rem; color: var(--text-secondary); }
55	.markdown-content li { margin: 0.25rem 0; }
56	.markdown-content code {
57	  background: #1e293b;
58	  padding: 0.15rem 0.4rem;
59	  border-radius: 4px;
60	  font-size: 0.875rem;
61	  color: #00FFA7;
62	}
63	.markdown-content pre {
64	  background: #1e293b;
65	  padding: 1rem;
66	  border-radius: 8px;
67	  overflow-x: auto;
68	  margin: 0.75rem 0;
69	}
70	.markdown-content pre code {
71	  background: none;
72	  padding: 0;
73	  color: var(--text-secondary);
74	}
75	.markdown-content table {
76	  width: 100%;
77	  border-collapse: collapse;
78	  margin: 0.75rem 0;
79	}
80	.markdown-content th, .markdown-content td {
81	  border: 1px solid var(--border);
82	  padding: 0.5rem 0.75rem;
83	  text-align: left;
84	}
85	.markdown-content th {
86	  background: #1e293b;
87	  font-weight: 600;
88	  color: var(--text-primary);
89	}
90	.markdown-content td {
91	  color: var(--text-secondary);
92	}
93	.markdown-content a {
94	  color: #00FFA7;
95	  text-decoration: none;
96	}
97	.markdown-content a:hover {
98	  text-decoration: underline;
99	}
100	.markdown-content blockquote {
101	  border-left: 3px solid #00FFA7;
102	  margin: 0.75rem 0;
103	  padding: 0.5rem 1rem;
104	  background: rgba(0, 255, 167, 0.05);
105	  color: var(--text-secondary);
106	}
107	.markdown-content hr {
108	  border: none;
109	  border-top: 1px solid var(--border);
110	  margin: 1.5rem 0;
111	}
112	
113	/* Skeleton animation */
114	@keyframes shimmer {
115	  0% { background-position: -200% 0; }
116	  100% { background-position: 200% 0; }
117	}
118	.skeleton {
119	  background: linear-gradient(90deg, #182230 25%, #1e293b 50%, #182230 75%);
120	  background-size: 200% 100%;
121	  animation: shimmer 1.5s infinite;
122	  border-radius: 8px;
123	}
