250	/**
251	 * Using the elevate system.
252	 * Automatic contrast adjustment.
253	 *
254	 * <element className="hover-elevate" />
255	 * <element className="active-elevate-2" />
256	 *
257	 * // Using the tailwind utility when a data attribute is "on"
258	 * <element className="toggle-elevate data-[state=on]:toggle-elevated" />
259	 * // Or manually controlling the toggle state
260	 * <element className="toggle-elevate toggle-elevated" />
261	 *
262	 * Elevation systems have to handle many states.
263	 * - not-hovered, vs. hovered vs. active  (three mutually exclusive states)
264	 * - toggled or not
265	 * - focused or not (this is not handled with these utilities)
266	 *
267	 * Even without handling focused or not, this is six possible combinations that
268	 * need to be distinguished from eachother visually.
269	 */
270	@layer utilities {
271	
272	  /* Hide ugly search cancel button in Chrome until we can style it properly */
273	  input[type="search"]::-webkit-search-cancel-button {
274	    @apply hidden;
275	  }
276	
277	  /* Placeholder styling for contentEditable div */
278	  [contenteditable][data-placeholder]:empty::before {
279	    content: attr(data-placeholder);
280	    color: hsl(var(--muted-foreground));
281	    pointer-events: none;
282	  }
283	
284	  /* .no-default-hover-elevate/no-default-active-elevate is an escape hatch so consumers of
285	   * buttons/badges can remove the automatic brightness adjustment on interactions
286	   * and program their own. */
287	  .no-default-hover-elevate {}
288	
289	  .no-default-active-elevate {}
290	
291	
292	  /**
293	   * Toggleable backgrounds go behind the content. Hoverable/active goes on top.
294	   * This way they can stack/compound. Both will overlap the parent's borders!
295	   * So borders will be automatically adjusted both on toggle, and hover/active,
296	   * and they will be compounded.
297	   */
298	  .toggle-elevate::before,
299	  .toggle-elevate-2::before {
300	    content: "";
301	    pointer-events: none;
302	    position: absolute;
303	    inset: 0px;
304	    /*border-radius: inherit;   match rounded corners */
305	    border-radius: inherit;
306	    z-index: -1;
307	    /* sits behind content but above backdrop */
308	  }
309	
310	  .toggle-elevate.toggle-elevated::before {
311	    background-color: var(--elevate-2);
312	  }
313	
314	  /* If there's a 1px border, adjust the inset so that it covers that parent's border */
315	  .border.toggle-elevate::before {
316	    inset: -1px;
317	  }
318	
319	  /* Does not work on elements with overflow:hidden! */
320	  .hover-elevate:not(.no-default-hover-elevate),
321	  .active-elevate:not(.no-default-active-elevate),
322	  .hover-elevate-2:not(.no-default-hover-elevate),
323	  .active-elevate-2:not(.no-default-active-elevate) {
324	    position: relative;
325	    z-index: 0;
326	  }
327	
328	  .hover-elevate:not(.no-default-hover-elevate)::after,
329	  .active-elevate:not(.no-default-active-elevate)::after,
330	  .hover-elevate-2:not(.no-default-hover-elevate)::after,
331	  .active-elevate-2:not(.no-default-active-elevate)::after {
332	    content: "";
333	    pointer-events: none;
334	    position: absolute;
335	    inset: 0px;
336	    /*border-radius: inherit;   match rounded corners */
337	    border-radius: inherit;
338	    z-index: 999;
339	    /* sits in front of content */
340	  }
341	
342	  .hover-elevate:hover:not(.no-default-hover-elevate)::after,
343	  .active-elevate:active:not(.no-default-active-elevate)::after {
344	    background-color: var(--elevate-1);
345	  }
346	
347	  .hover-elevate-2:hover:not(.no-default-hover-elevate)::after,
348	  .active-elevate-2:active:not(.no-default-active-elevate)::after {
349	    background-color: var(--elevate-2);
350	  }
351	
352	  /* If there's a 1px border, adjust the inset so that it covers that parent's border */
353	  .border.hover-elevate:not(.no-hover-interaction-elevate)::after,
354	  .border.active-elevate:not(.no-active-interaction-elevate)::after,
355	  .border.hover-elevate-2:not(.no-hover-interaction-elevate)::after,
356	  .border.active-elevate-2:not(.no-active-interaction-elevate)::after,
357	  .border.hover-elevate:not(.no-hover-interaction-elevate)::after {
358	    inset: -1px;
359	  }
360	}
