2	import {
3	  clearStoredCustomTheme,
4	  getStoredCustomTheme,
5	  parseThemeInput,
6	  setStoredCustomTheme,
7	  syncCustomThemeFromStorage,
8	  type CustomThemeData,
9	} from './customTheme';
10	
11	export type ThemeName = 'claw';
12	export type ThemeMode = 'system' | 'light' | 'dark';
13	export type ResolvedTheme = 'light' | 'dark';
14	
15	export type ThemeSelection = {
16	  theme: ThemeName;
17	  mode: ThemeMode;
18	};
19	
20	const THEME_SELECTION_KEY = 'clawhub-theme-selection';
21	const THEME_KEY = 'clawhub-theme';
22	const LEGACY_THEME_KEY = 'clawdhub-theme';
23	const THEME_NAME_KEY = 'clawhub-theme-name';
24	const THEME_CHANGE_EVENT = 'clawhub:themechange';
25	
26	export const THEME_OPTIONS: Array<{ value: ThemeName; label: string; description: string }> = [
27	  {
28	    value: 'claw',
29	    label: 'Claw',
30	    description: 'OpenClaw black, white, and red.',
31	  },
32	];
33	
34	export const THEME_FAMILY_OPTIONS = THEME_OPTIONS;
35	
36	const VALID_THEME_NAMES = new Set<ThemeName>(['claw']);
37	const VALID_THEME_MODES = new Set<ThemeMode>(['system', 'light', 'dark']);
38	
39	const LEGACY_MAP: Record<string, ThemeSelection> = {
40	  dark: { theme: 'claw', mode: 'dark' },
41	  light: { theme: 'claw', mode: 'light' },
42	  system: { theme: 'claw', mode: 'system' },
43	  defaultTheme: { theme: 'claw', mode: 'dark' },
44	  docsTheme: { theme: 'claw', mode: 'light' },
45	  lightTheme: { theme: 'claw', mode: 'dark' },
46	  landingTheme: { theme: 'claw', mode: 'dark' },
47	  newTheme: { theme: 'claw', mode: 'dark' },
48	  openknot: { theme: 'claw', mode: 'dark' },
49	  fieldmanual: { theme: 'claw', mode: 'dark' },
50	  clawdash: { theme: 'claw', mode: 'light' },
51	};
52	
53	function parseThemeSelection(themeRaw: unknown, modeRaw: unknown): ThemeSelection {
54	  const theme = typeof themeRaw === 'string' ? themeRaw : '';
55	  const mode = typeof modeRaw === 'string' ? modeRaw : '';
56	
57	  const normalizedTheme = VALID_THEME_NAMES.has(theme as ThemeName)
58	    ? (theme as ThemeName)
59	    : (LEGACY_MAP[theme]?.theme ?? 'claw');
60	  const normalizedMode = VALID_THEME_MODES.has(mode as ThemeMode)
61	    ? (mode as ThemeMode)
62	    : (LEGACY_MAP[theme]?.mode ?? 'system');
63	
64	  return { theme: normalizedTheme, mode: normalizedMode };
65	}
66	
67	function persistThemeSelection(selection: ThemeSelection) {
68	  if (typeof window === 'undefined') return;
69	  window.localStorage.setItem(THEME_SELECTION_KEY, JSON.stringify(selection));
70	  window.localStorage.setItem(THEME_KEY, selection.mode);
71	  window.localStorage.setItem(THEME_NAME_KEY, selection.theme);
72	}
73	
74	export function getStoredThemeSelection(): ThemeSelection {
75	  if (typeof window === 'undefined') return { theme: 'claw', mode: 'system' };
76	
77	  try {
78	    const storedSelection = window.localStorage.getItem(THEME_SELECTION_KEY);
79	    if (storedSelection) {
80	      const parsed = JSON.parse(storedSelection) as Partial<ThemeSelection>;
81	      return parseThemeSelection(parsed.theme, parsed.mode);
82	    }
83	  } catch {
84	    // fall through to legacy keys
85	  }
86	
87	  const storedMode = window.localStorage.getItem(THEME_KEY);
88	  const storedTheme = window.localStorage.getItem(THEME_NAME_KEY);
89	  if (storedMode || storedTheme) {
90	    return parseThemeSelection(storedTheme, storedMode);
91	  }
92	
93	  const legacy = window.localStorage.getItem(LEGACY_THEME_KEY);
94	  if (legacy) {
95	    return parseThemeSelection(legacy, undefined);
96	  }
97	
98	  return { theme: 'claw', mode: 'system' };
99	}
100	
101	export function getStoredTheme(): ThemeMode {
102	  return getStoredThemeSelection().mode;
103	}
104	
105	export function getStoredThemeName(): ThemeName {
106	  return getStoredThemeSelection().theme;
107	}
108	
109	export function getThemeFamilyLabel(theme: ThemeName): string {
110	  return THEME_OPTIONS.find((option) => option.value === theme)?.label ?? 'Claw';
111	}
112	
113	function resolveMode(mode: ThemeMode): ResolvedTheme {
114	  if (mode !== 'system') return mode;
115	  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') return 'light';
116	  return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
117	}
118	
119	export function resolveTheme(theme: ThemeName, mode: ThemeMode): ResolvedTheme {
120	  void theme;
121	  return resolveMode(mode);
122	}
123	
124	export function isDarkResolvedTheme(resolvedTheme: string | null | undefined): boolean {
125	  return resolvedTheme === 'dark';
126	}
127	
128	export function isDarkThemeResolved(): boolean {
129	  if (typeof document === 'undefined') return false;
130	  return isDarkResolvedTheme(document.documentElement.dataset.themeResolved);
131	}
132	
133	export function applyTheme(selectionOrMode: ThemeSelection | ThemeMode, theme: ThemeName = 'claw') {
134	  const selection = typeof selectionOrMode === 'string' ? { theme, mode: selectionOrMode } : selectionOrMode;
135	  applyThemeSelection(selection);
136	}
137	
138	export function applyThemeSelection(selection: ThemeSelection) {
139	  if (typeof document === 'undefined') return;
140	  const resolved = resolveTheme(selection.theme, selection.mode);
141	  document.documentElement.dataset.theme = resolved;
142	  document.documentElement.dataset.themeResolved = resolved;
143	  document.documentElement.dataset.themeMode = selection.mode;
144	  document.documentElement.dataset.themeFamily = selection.theme;
145	  document.documentElement.classList.toggle('dark', isDarkResolvedTheme(resolved));
146	  if (typeof window !== 'undefined') {
147	    window.dispatchEvent(new CustomEvent(THEME_CHANGE_EVENT));
148	  }
149	}
150	
151	export function onThemeChange(handler: () => void) {
152	  if (typeof window === 'undefined') return () => {};
153	  window.addEventListener(THEME_CHANGE_EVENT, handler);
154	  return () => window.removeEventListener(THEME_CHANGE_EVENT, handler);
155	}
156	
157	export function useThemeMode() {
158	  const [selection, setSelection] = useState<ThemeSelection>({ theme: 'claw', mode: 'system' });
159	  const [isHydrated, setIsHydrated] = useState(false);
160	  const [customTheme, setCustomTheme] = useState<CustomThemeData | null>(null);
161	
162	  useEffect(() => {
163	    setSelection(getStoredThemeSelection());
164	    setCustomTheme(getStoredCustomTheme());
165	    setIsHydrated(true);
166	  }, []);
167	
168	  useEffect(() => {
169	    if (!isHydrated) return () => {};
170	    applyThemeSelection(selection);
171	    persistThemeSelection(selection);
172	    syncCustomThemeFromStorage();
173	
174	    if (selection.mode !== 'system' || typeof window === 'undefined' || typeof window.matchMedia !== 'function') {
175	      return () => {};
176	    }
177	
178	    const media = window.matchMedia('(prefers-color-scheme: dark)');
179	    const handler = () => {
180	      applyThemeSelection(selection);
181	      syncCustomThemeFromStorage();
182	    };
183	
184	    if (typeof media.addEventListener === 'function') {
185	      media.addEventListener('change', handler);
186	      return () => media.removeEventListener('change', handler);
187	    }
188	
189	    media.addListener(handler);
190	    return () => media.removeListener(handler);
191	  }, [isHydrated, selection]);
192	
193	  const importCustomTheme = async (input: string) => {
194	    const parsed = await parseThemeInput(input);
195	    const theme = {
196	      ...parsed,
197	      source: input.trim(),
198	    };
199	    setStoredCustomTheme(theme);
200	    setCustomTheme(theme);
201	    syncCustomThemeFromStorage();
202	    return theme;
203	  };
204	
205	  const clearCustomTheme = () => {
206	    clearStoredCustomTheme();
207	    setCustomTheme(null);
208	    syncCustomThemeFromStorage();
209	  };
210	
211	  return {
212	    theme: selection.theme,
213	    family: selection.theme,
214	    mode: selection.mode,
215	    selection,
216	    customTheme,
217	    setTheme: (theme: ThemeName) => setSelection((current) => ({ ...current, theme })),
218	    setFamily: (theme: ThemeName) => setSelection((current) => ({ ...current, theme })),
219	    setMode: (mode: ThemeMode) => setSelection((current) => ({ ...current, mode })),
220	    importCustomTheme,
221	    clearCustomTheme,
222	  };
223	}
