38	  globalThis.window as WindowWithMatchMedia | undefined;
39	
40	const hasReducedMotionPreference = (): boolean => {
41	  const currentWindow = resolveWindow();
42	  if (!currentWindow || typeof currentWindow.matchMedia !== "function") return false;
43	  return currentWindow.matchMedia("(prefers-reduced-motion: reduce)").matches ?? false;
44	};
45	
46	const cleanupThemeTransition = (root: HTMLElement) => {
47	  root.classList.remove("theme-transition");
48	  root.style.removeProperty("--theme-switch-x");
49	  root.style.removeProperty("--theme-switch-y");
50	};
51	
52	export const startThemeTransition = ({
53	  nextTheme,
54	  setTheme,
55	  context,
56	  onBeforeThemeChange,
57	  onAfterThemeChange,
58	  currentTheme,
59	}: ThemeTransitionOptions) => {
60	  if (currentTheme === nextTheme) return;
61	
62	  const documentReference = globalThis.document ?? null;
63	  if (!documentReference) {
64	    onBeforeThemeChange?.();
65	    setTheme(nextTheme);
66	    onAfterThemeChange?.();
67	    return;
68	  }
69	
70	  const root = documentReference.documentElement;
71	  const document_ = documentReference as DocumentWithViewTransition;
72	  const prefersReducedMotion = hasReducedMotionPreference();
73	
74	  const applyTheme = () => {
75	    onBeforeThemeChange?.();
76	    flushSync(() => {
77	      setTheme(nextTheme);
78	    });
79	    onAfterThemeChange?.();
80	  };
81	
82	  const canUseViewTransition = Boolean(document_.startViewTransition) && !prefersReducedMotion;
83	  if (canUseViewTransition) {
84	    let xPercent = 0.5;
85	    let yPercent = 0.5;
86	
87	    const currentWindow = resolveWindow();
88	    if (
89	      context?.pointerClientX !== undefined &&
90	      context?.pointerClientY !== undefined &&
91	      currentWindow
92	    ) {
93	      xPercent = clamp01(context.pointerClientX / currentWindow.innerWidth);
94	      yPercent = clamp01(context.pointerClientY / currentWindow.innerHeight);
95	    } else if (context?.element) {
96	      const rect = context.element.getBoundingClientRect();
97	      if (rect.width > 0 && rect.height > 0 && currentWindow) {
98	        xPercent = clamp01((rect.left + rect.width / 2) / currentWindow.innerWidth);
99	        yPercent = clamp01((rect.top + rect.height / 2) / currentWindow.innerHeight);
100	      }
101	    }
102	
103	    root.style.setProperty("--theme-switch-x", `${xPercent * 100}%`);
104	    root.style.setProperty("--theme-switch-y", `${yPercent * 100}%`);
105	    root.classList.add("theme-transition");
106	
107	    try {
108	      const transition = document_.startViewTransition?.(() => {
109	        applyTheme();
110	      });
111	      if (transition?.finished === undefined) {
112	        cleanupThemeTransition(root);
113	      } else {
114	        const handleTransitionFinish = async () => {
115	          try {
116	            await transition.finished;
117	          } catch {
118	            // swallow transition cancellation errors
119	          } finally {
120	            cleanupThemeTransition(root);
121	          }
122	        };
123	        void handleTransitionFinish();
124	      }
125	    } catch {
126	      cleanupThemeTransition(root);
127	      applyTheme();
128	    }
129	    return;
130	  }
131	
132	  applyTheme();
133	  cleanupThemeTransition(root);
134	};
