396	.code-comment  { color: #6C7086; }  /* muted gray — // comments */
397	.code-number   { color: #FAB387; }  /* peach — numbers */
398	.code-property { color: #F9E2AF; }  /* yellow — object keys */
399	.code-operator { color: #94E2D5; }  /* teal — =, =>, +, etc. */
400	.code-tag      { color: #F38BA8; }  /* pink — HTML tags */
401	.code-attr     { color: #F9E2AF; }  /* yellow — HTML attributes */
402	.code-value    { color: #A6E3A1; }  /* green — attribute values */
